13 | import java.util.ArrayList;
14 | import java.util.List;
15 | 
16 | /**
17 |  * ┌──────────────────────────────────────────────────────────────────────────┐
18 |  * │  MOCK ANALYSIS ENGINE — NOT ACTUAL AI                                    │
19 |  * │                                                                          │
20 |  * │  This service simulates an AI code-review by pattern-matching the        │
21 |  * │  submitted codeDiff and returning deterministic sample findings.         │
22 |  * │                                                                          │
23 |  * │  It is intentionally labelled MOCK throughout the codebase.             │
24 |  * │  A real IBM Granite / watsonx analysis engine will replace this in      │
25 |  * │  a future task once the IBM Bob integration is complete.                │
26 |  * └──────────────────────────────────────────────────────────────────────────┘
27 |  *
28 |  * The method runs asynchronously so that POST /reviews returns immediately
29 |  * while analysis proceeds in the background.
30 |  */
31 | @Service
32 | public class MockAnalysisService {
33 | 
34 |     private static final Logger log = LoggerFactory.getLogger(MockAnalysisService.class);
35 | 
36 |     private final ReviewRepository reviewRepository;
37 |     private final FindingRepository findingRepository;
38 | 
39 |     public MockAnalysisService(ReviewRepository reviewRepository,
40 |                                FindingRepository findingRepository) {
41 |         this.reviewRepository = reviewRepository;
42 |         this.findingRepository = findingRepository;
43 |     }
44 | 
45 |     /**
46 |      * Runs mock analysis asynchronously.
47 |      *
48 |      * <p>Steps:
49 |      * <ol>
50 |      *   <li>Mark review ANALYZING, progress 10%</li>
51 |      *   <li>Delete any existing findings for this review (idempotent re-run)</li>
52 |      *   <li>Scan the diff for known patterns and create findings</li>
53 |      *   <li>Mark review COMPLETED, progress 100%</li>
54 |      * </ol>
55 |      *
56 |      * <p>If an unexpected error occurs the review is marked FAILED and no
57 |      * findings are persisted from that run.
58 |      *
59 |      * @param reviewId the ID of the review to analyse
60 |      */
61 |     @Async
62 |     @Transactional
63 |     public void analyzeAsync(Long reviewId) {
64 |         log.info("[MOCK] Starting mock analysis for review {}", reviewId);
65 | 
66 |         Review review = reviewRepository.findById(reviewId).orElse(null);
67 |         if (review == null) {
68 |             log.warn("[MOCK] Review {} not found – skipping analysis", reviewId);
69 |             return;
70 |         }
71 | 
72 |         try {
73 |             // Step 1 — mark as ANALYZING
74 |             review.setStatus("ANALYZING");
75 |             review.setProgress(10);
76 |             reviewRepository.save(review);
77 | 
78 |             // Step 2 — remove stale findings so re-runs don't duplicate
79 |             findingRepository.deleteByReview_Id(reviewId);
80 | 
81 |             // Step 3 — build findings from diff patterns
82 |             String diff = review.getCodeDiff() == null ? "" : review.getCodeDiff();
83 |             List<Finding> findings = buildFindings(review, diff);
84 | 
85 |             // Step 4 — progress update after scan
86 |             review.setProgress(70);
87 |             reviewRepository.save(review);
88 | 
89 |             // Step 5 — persist findings
90 |             findingRepository.saveAll(findings);
91 | 
92 |             // Step 6 — mark COMPLETED
93 |             review.setStatus("COMPLETED");
94 |             review.setProgress(100);
95 |             reviewRepository.save(review);
96 | 
97 |             log.info("[MOCK] Completed mock analysis for review {} — {} findings", reviewId, findings.size());
98 | 
99 |         } catch (Exception ex) {
100 |             log.error("[MOCK] Analysis failed for review {}: {}", reviewId, ex.getMessage(), ex);
101 |             try {
102 |                 review.setStatus("FAILED");
103 |                 reviewRepository.save(review);
104 |             } catch (Exception saveEx) {
105 |                 log.error("[MOCK] Could not persist FAILED status for review {}", reviewId, saveEx);
106 |             }
107 |         }
108 |     }
109 | 
110 |     // ── Pattern-based mock finding generation ──────────────────────────────
111 | 
112 |     /**
113 |      * Scans the diff for patterns and returns a list of mock findings.
114 |      *
115 |      * <p>Patterns detected (all MOCK / illustrative):
116 |      * <ul>
117 |      *   <li>Hardcoded credentials / secrets in added lines</li>
118 |      *   <li>SQL string concatenation (injection risk)</li>
119 |      *   <li>TODO / FIXME comments left in added lines</li>
120 |      *   <li>Catch blocks that swallow exceptions silently</li>
121 |      *   <li>Missing null-check patterns (e.g. .get() without isPresent)</li>
122 |      *   <li>Generic "code quality" note on large diffs</li>
123 |      * </ul>
124 |      *
125 |      * <p>If the diff is blank, one informational finding is added noting that
126 |      * there was nothing to analyse.
127 |      */
128 |     private List<Finding> buildFindings(Review review, String diff) {
129 |         List<Finding> findings = new ArrayList<>();
130 | 
131 |         if (diff.isBlank()) {
132 |             findings.add(new Finding(
133 |                     review,
134 |                     "Empty diff submitted",
135 |                     "low",
136 |                     "quality",
137 |                     "unknown",
138 |                     0,
139 |                     "No code diff was provided. ThirdEye could not analyse anything.",
140 |                     "Submit a non-empty unified diff to receive meaningful findings."
141 |             ));
142 |             return findings;
143 |         }
144 | 
145 |         String[] lines = diff.split("\n");
146 | 
147 |         for (int i = 0; i < lines.length; i++) {
148 |             String raw = lines[i];
149 |             // Only inspect added lines (lines starting with '+' but not the diff header '+++')
150 |             if (!raw.startsWith("+") || raw.startsWith("+++")) continue;
151 | 
152 |             String line = raw.substring(1).trim();
153 |             int lineNumber = i + 1;
154 | 
155 |             // ── Security: hardcoded credentials ──────────────────────────────
156 |             if (containsCredentialPattern(line)) {
157 |                 findings.add(new Finding(
158 |                         review,
159 |                         "Hardcoded credential detected",
160 |                         "critical",
161 |                         "security",
162 |                         guessFile(diff, i),
163 |                         lineNumber,
164 |                         "[MOCK] A hardcoded password, secret, or API key was detected in the diff. " +
165 |                         "Hardcoded credentials can leak into version-control history and logs.",
166 |                         "Move the secret to an environment variable or a secrets manager (e.g. HashiCorp Vault, " +
167 |                         "AWS Secrets Manager). Never commit credentials to source control."
168 |                 ));
169 |             }
170 | 
171 |             // ── Security: SQL string concatenation ───────────────────────────
172 |             if (containsSqlConcatPattern(line)) {
173 |                 findings.add(new Finding(
174 |                         review,
175 |                         "Potential SQL injection via string concatenation",
176 |                         "high",
177 |                         "security",
178 |                         guessFile(diff, i),
179 |                         lineNumber,
180 |                         "[MOCK] The diff contains SQL built by string concatenation with user-controlled input. " +
181 |                         "This is a classic SQL injection vector.",
182 |                         "Use parameterised queries or a prepared statement. " +
183 |                         "Spring Data JPA query methods and @Query with :param placeholders are safe alternatives."
184 |                 ));
185 |             }
186 | 
187 |             // ── Quality: TODO / FIXME left in code ───────────────────────────
188 |             if (containsTodoFixme(line)) {
189 |                 findings.add(new Finding(
190 |                         review,
191 |                         "TODO / FIXME left in submitted code",
192 |                         "low",
193 |                         "quality",
194 |                         guessFile(diff, i),
195 |                         lineNumber,
196 |                         "[MOCK] A TODO or FIXME comment was found in a newly added line. " +
197 |                         "Unresolved annotations indicate incomplete implementation.",
198 |                         "Resolve the TODO before merging. If work is deferred, create a tracked issue instead."
199 |                 ));
200 |             }
201 | 
202 |             // ── Bugs: empty catch block ───────────────────────────────────────
203 |             if (containsEmptyCatch(line)) {
204 |                 findings.add(new Finding(
205 |                         review,
206 |                         "Exception silently swallowed in catch block",
207 |                         "medium",
208 |                         "bugs",
209 |                         guessFile(diff, i),
210 |                         lineNumber,
211 |                         "[MOCK] A catch block appears to swallow exceptions without logging or rethrowing. " +
212 |                         "This hides failures and makes debugging very difficult.",
213 |                         "At minimum, log the exception (log.error(\"...\", ex)). " +
214 |                         "Consider whether the exception should propagate to the caller."
215 |                 ));
216 |             }
217 | 
218 |             // ── Bugs: Optional.get() without isPresent ────────────────────────
219 |             if (containsOptionalGetWithoutCheck(line)) {
220 |                 findings.add(new Finding(
221 |                         review,
222 |                         "Optional.get() called without presence check",
223 |                         "high",
224 |                         "bugs",
225 |                         guessFile(diff, i),
226 |                         lineNumber,
227 |                         "[MOCK] Optional.get() is called without a preceding isPresent() or orElse() guard. " +
228 |                         "This will throw NoSuchElementException at runtime when the value is absent.",
229 |                         "Use optional.orElseThrow(() -> new ResourceNotFoundException(...)) or " +
230 |                         "optional.ifPresent(...) to handle the empty case safely."
231 |                 ));
232 |             }
233 |         }
234 | 
235 |         // ── Coverage: no tests in diff ────────────────────────────────────────
236 |         boolean hasTestChanges = diff.contains("@Test") || diff.contains("test") || diff.contains("Test");
237 |         if (!hasTestChanges) {
238 |             findings.add(new Finding(
239 |                     review,
240 |                     "No test changes detected in diff",
241 |                     "medium",
242 |                     "coverage",
243 |                     "unknown",
244 |                     0,
245 |                     "[MOCK] The submitted diff does not appear to include any test file changes. " +
246 |                     "Adding or updating tests alongside feature code maintains coverage.",
247 |                     "Add unit or integration tests that exercise the changed code paths. " +
248 |                     "Aim for at least one happy-path and one error-path test per new method."
249 |             ));
250 |         }
251 | 
252 |         // ── Quality: large diff warning ───────────────────────────────────────
253 |         long addedLines = java.util.Arrays.stream(lines)
254 |                 .filter(l -> l.startsWith("+") && !l.startsWith("+++"))
255 |                 .count();
256 |         if (addedLines > 200) {
257 |             findings.add(new Finding(
258 |                     review,
259 |                     "Large changeset — consider splitting",
260 |                     "low",
261 |                     "quality",
262 |                     "unknown",
263 |                     0,
264 |                     "[MOCK] The diff adds more than 200 lines. Large pull requests are harder to review " +
265 |                     "thoroughly and statistically introduce more defects.",
266 |                     "Split this change into smaller, independently reviewable pull requests " +
267 |                     "focused on a single concern."
268 |             ));
269 |         }
270 | 
271 |         return findings;
272 |     }
273 | 
274 |     // ── Pattern helpers ───────────────────────────────────────────────────────
275 | 
276 |     private boolean containsCredentialPattern(String line) {
277 |         String lower = line.toLowerCase();
278 |         return (lower.contains("password") || lower.contains("passwd") ||
279 |                 lower.contains("secret") || lower.contains("apikey") ||
280 |                 lower.contains("api_key") || lower.contains("token"))
281 |                && (line.contains("=") || line.contains(":"))
282 |                && (line.contains("\"") || line.contains("'"));
283 |     }
284 | 
285 |     private boolean containsSqlConcatPattern(String line) {
286 |         String lower = line.toLowerCase();
287 |         return lower.contains("select") && lower.contains("+") &&
288 |                (lower.contains("where") || lower.contains("from"));
289 |     }
290 | 
291 |     private boolean containsTodoFixme(String line) {
292 |         String upper = line.toUpperCase();
293 |         return upper.contains("TODO") || upper.contains("FIXME") || upper.contains("HACK");
294 |     }
295 | 
296 |     private boolean containsEmptyCatch(String line) {
297 |         // Matches: "} catch" with nothing meaningful after it on the same line
298 |         return line.matches(".*}\\s*catch\\s*\\(.*\\)\\s*\\{?\\s*") ||
299 |                line.matches(".*catch\\s*\\(.*\\)\\s*\\{\\s*}.*");
300 |     }
301 | 
302 |     private boolean containsOptionalGetWithoutCheck(String line) {
303 |         return line.contains(".get()") && !line.contains("isPresent") &&
304 |                !line.contains("orElse") && !line.contains("ifPresent");
305 |     }
306 | 
307 |     /**
308 |      * Attempts to extract the nearest diff file header above line {@code lineIndex}.
309 |      * Returns "unknown" when no header is found.
310 |      */
311 |     private String guessFile(String diff, int lineIndex) {
312 |         String[] lines = diff.split("\n");
313 |         for (int i = lineIndex; i >= 0; i--) {
314 |             String l = lines[i];
315 |             if (l.startsWith("+++ ")) {
316 |                 return l.replace("+++ b/", "").replace("+++ ", "").trim();
317 |             }
318 |             if (l.startsWith("--- ")) {
319 |                 return l.replace("--- a/", "").replace("--- ", "").trim();
320 |             }
321 |         }
322 |         return "unknown";
323 |     }
324 | }
