19 |  * ┌──────────────────────────────────────────────────────────────────────────┐
20 |  * │  MOCK TEST GENERATION ENGINE — NOT ACTUAL AI                             │
21 |  * │                                                                          │
22 |  * │  Generates template test stubs based on persisted findings.             │
23 |  * │  Tests are PENDING (not actually executed).                              │
24 |  * │  Real IBM Granite / watsonx test generation replaces this later.        │
25 |  * └──────────────────────────────────────────────────────────────────────────┘
26 |  */
27 | @Service
28 | public class TestGenerationService {
29 | 
30 |     private static final Logger log = LoggerFactory.getLogger(TestGenerationService.class);
31 | 
32 |     private final ReviewRepository reviewRepository;
33 |     private final FindingRepository findingRepository;
34 |     private final GeneratedTestRepository testRepository;
35 | 
36 |     public TestGenerationService(ReviewRepository reviewRepository,
37 |                                  FindingRepository findingRepository,
38 |                                  GeneratedTestRepository testRepository) {
39 |         this.reviewRepository = reviewRepository;
40 |         this.findingRepository = findingRepository;
41 |         this.testRepository = testRepository;
42 |     }
