            ps.setLong(1, id);
            ps.setLong(2, reviewId);
            ps.setString(3, name);
            ps.setString(4, file);
            ps.setString(5, status);
            if (duration == null) ps.setNull(6, Types.VARCHAR); else ps.setString(6, duration);
