28 | 
29 |     /** 404 – resource not found */
30 |     @ExceptionHandler(ResourceNotFoundException.class)
31 |     public ResponseEntity<Map<String, Object>> handleNotFound(ResourceNotFoundException ex) {
32 |         return build(HttpStatus.NOT_FOUND, ex.getMessage());
33 |     }
34 | 
35 |     /** 400 – Bean Validation failures (@Valid) */
36 |     @ExceptionHandler(MethodArgumentNotValidException.class)
37 |     public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
38 |         String details = ex.getBindingResult()
39 |                 .getFieldErrors()
40 |                 .stream()
41 |                 .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
42 |                 .collect(Collectors.joining("; "));
43 |         return build(HttpStatus.BAD_REQUEST, details);
44 |     }
45 | 
46 |     /** 400 – illegal arguments */
47 |     @ExceptionHandler(IllegalArgumentException.class)
48 |     public ResponseEntity<Map<String, Object>> handleIllegalArg(IllegalArgumentException ex) {
49 |         return build(HttpStatus.BAD_REQUEST, ex.getMessage());
50 |     }
51 | 
52 |     /** 500 – unexpected errors (message only, no stack trace) */
53 |     @ExceptionHandler(Exception.class)
54 |     public ResponseEntity<Map<String, Object>> handleGeneric(Exception ex) {
55 |         return build(HttpStatus.INTERNAL_SERVER_ERROR,
56 |                 "An unexpected error occurred. Please try again later.");
57 |     }
58 | 
59 |     // ── helpers ──────────────────────────────────────────────────────────────
60 | 
61 |     private ResponseEntity<Map<String, Object>> build(HttpStatus status, String message) {
62 |         Map<String, Object> body = new LinkedHashMap<>();
63 |         body.put("timestamp", LocalDateTime.now().toString());
64 |         body.put("status", status.value());
65 |         body.put("error", status.getReasonPhrase());
66 |         body.put("message", message);
