package com.thirdeye.backend.service;

import com.thirdeye.backend.entity.Finding;
import com.thirdeye.backend.entity.Review;
import com.thirdeye.backend.repository.FindingRepository;
import com.thirdeye.backend.repository.ReviewRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;

/**
 * ┌──────────────────────────────────────────────────────────────────────────┐
 * │  MOCK ANALYSIS ENGINE — NOT ACTUAL AI                                    │
 * │                                                                          │
 * │  This service simulates an AI code-review by pattern-matching the        │
 * │  submitted codeDiff and returning deterministic sample findings.         │
 * │                                                                          │
 * │  It is intentionally labelled MOCK throughout the codebase.             │
 * │  A real IBM Granite / watsonx analysis engine will replace this in      │
 * │  a future task once the IBM Bob integration is complete.                │
 * └──────────────────────────────────────────────────────────────────────────┘
 *
 * The method runs asynchronously so that POST /reviews returns immediately
 * while analysis proceeds in the background.
 */
@Service
public class MockAnalysisService {

    private static final Logger log = LoggerFactory.getLogger(MockAnalysisService.class);

    private final ReviewRepository reviewRepository;
    private final FindingRepository findingRepository;

    public MockAnalysisService(ReviewRepository reviewRepository,
                               FindingRepository findingRepository) {
        this.reviewRepository = reviewRepository;
        this.findingRepository = findingRepository;
    }

    /**
     * Runs mock analysis asynchronously.
     *
     * <p>Steps:
     * <ol>
     *   <li>Mark review ANALYZING, progress 10%</li>
     *   <li>Delete any existing findings for this review (idempotent re-run)</li>
     *   <li>Scan the diff for known patterns and create findings</li>
     *   <li>Mark review COMPLETED, progress 100%</li>
     * </ol>
     *
     * <p>If an unexpected error occurs the review is marked FAILED and no
     * findings are persisted from that run.
     *
     * @param reviewId the ID of the review to analyse
     */
    @Async
    @Transactional
    public void analyzeAsync(Long reviewId) {
        log.info("[MOCK] Starting mock analysis for review {}", reviewId);

        Review review = reviewRepository.findById(reviewId).orElse(null);
        if (review == null) {
            log.warn("[MOCK] Review {} not found – skipping analysis", reviewId);
            return;
        }

        try {
            // Step 1 — mark as ANALYZING
            review.setStatus("ANALYZING");
            review.setProgress(10);
            reviewRepository.save(review);

            // Step 2 — remove stale findings so re-runs don't duplicate
            findingRepository.deleteByReview_Id(reviewId);

            // Step 3 — build findings from diff patterns
            String diff = review.getCodeDiff() == null ? "" : review.getCodeDiff();
            List<Finding> findings = buildFindings(review, diff);

            // Step 4 — progress update after scan
            review.setProgress(70);
            reviewRepository.save(review);

            // Step 5 — persist findings
            findingRepository.saveAll(findings);

            // Step 6 — mark COMPLETED
            review.setStatus("COMPLETED");
            review.setProgress(100);
            reviewRepository.save(review);

            log.info("[MOCK] Completed mock analysis for review {} — {} findings", reviewId, findings.size());

        } catch (Exception ex) {
            log.error("[MOCK] Analysis failed for review {}: {}", reviewId, ex.getMessage(), ex);
            try {
                review.setStatus("FAILED");
                reviewRepository.save(review);
            } catch (Exception saveEx) {
                log.error("[MOCK] Could not persist FAILED status for review {}", reviewId, saveEx);
            }
        }
    }

    // ── Pattern-based mock finding generation ──────────────────────────────

    /**
     * Scans the diff for patterns and returns a list of mock findings.
     *
     * <p>Patterns detected (all MOCK / illustrative):
     * <ul>
     *   <li>Hardcoded credentials / secrets in added lines</li>
     *   <li>SQL string concatenation (injection risk)</li>
     *   <li>TODO / FIXME comments left in added lines</li>
     *   <li>Catch blocks that swallow exceptions silently</li>
     *   <li>Missing null-check patterns (e.g. .get() without isPresent)</li>
     *   <li>Generic "code quality" note on large diffs</li>
     * </ul>
     *
     * <p>If the diff is blank, one informational finding is added noting that
     * there was nothing to analyse.
     */
    private List<Finding> buildFindings(Review review, String diff) {
        List<Finding> findings = new ArrayList<>();

        if (diff.isBlank()) {
            findings.add(new Finding(
                    review,
                    "Empty diff submitted",
                    "low",
                    "quality",
                    "unknown",
                    0,
                    "No code diff was provided. ThirdEye could not analyse anything.",
                    "Submit a non-empty unified diff to receive meaningful findings."
            ));
            return findings;
        }

        String[] lines = diff.split("\n");

        for (int i = 0; i < lines.length; i++) {
            String raw = lines[i];
            // Only inspect added lines (lines starting with '+' but not the diff header '+++')
            if (!raw.startsWith("+") || raw.startsWith("+++")) continue;

            String line = raw.substring(1).trim();
            int lineNumber = i + 1;

            // ── Security: hardcoded credentials ──────────────────────────────
            if (containsCredentialPattern(line)) {
                findings.add(new Finding(
                        review,
                        "Hardcoded credential detected",
                        "critical",
                        "security",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] A hardcoded password, secret, or API key was detected in the diff. " +
                        "Hardcoded credentials can leak into version-control history and logs.",
                        "Move the secret to an environment variable or a secrets manager (e.g. HashiCorp Vault, " +
                        "AWS Secrets Manager). Never commit credentials to source control."
                ));
            }

            // ── Security: SQL string concatenation ───────────────────────────
            if (containsSqlConcatPattern(line)) {
                findings.add(new Finding(
                        review,
                        "Potential SQL injection via string concatenation",
                        "high",
                        "security",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] The diff contains SQL built by string concatenation with user-controlled input. " +
                        "This is a classic SQL injection vector.",
                        "Use parameterised queries or a prepared statement. " +
                        "Spring Data JPA query methods and @Query with :param placeholders are safe alternatives."
                ));
            }

            // ── Quality: TODO / FIXME left in code ───────────────────────────
            if (containsTodoFixme(line)) {
                findings.add(new Finding(
                        review,
                        "TODO / FIXME left in submitted code",
                        "low",
                        "quality",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] A TODO or FIXME comment was found in a newly added line. " +
                        "Unresolved annotations indicate incomplete implementation.",
                        "Resolve the TODO before merging. If work is deferred, create a tracked issue instead."
                ));
            }

            // ── Bugs: empty catch block ───────────────────────────────────────
            if (containsEmptyCatch(line)) {
                findings.add(new Finding(
                        review,
                        "Exception silently swallowed in catch block",
                        "medium",
                        "bugs",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] A catch block appears to swallow exceptions without logging or rethrowing. " +
                        "This hides failures and makes debugging very difficult.",
                        "At minimum, log the exception (log.error(\"...\", ex)). " +
                        "Consider whether the exception should propagate to the caller."
                ));
            }

            // ── Bugs: Optional.get() without isPresent ────────────────────────
            if (containsOptionalGetWithoutCheck(line)) {
                findings.add(new Finding(
                        review,
                        "Optional.get() called without presence check",
                        "high",
                        "bugs",
                        guessFile(diff, i),
                        lineNumber,
                        "[MOCK] Optional.get() is called without a preceding isPresent() or orElse() guard. " +
                        "This will throw NoSuchElementException at runtime when the value is absent.",
                        "Use optional.orElseThrow(() -> new ResourceNotFoundException(...)) or " +
                        "optional.ifPresent(...) to handle the empty case safely."
                ));
            }
        }

        // ── Coverage: no tests in diff ────────────────────────────────────────
        boolean hasTestChanges = diff.contains("@Test") || diff.contains("test") || diff.contains("Test");
        if (!hasTestChanges) {
            findings.add(new Finding(
                    review,
                    "No test changes detected in diff",
                    "medium",
                    "coverage",
                    "unknown",
                    0,
                    "[MOCK] The submitted diff does not appear to include any test file changes. " +
                    "Adding or updating tests alongside feature code maintains coverage.",
                    "Add unit or integration tests that exercise the changed code paths. " +
                    "Aim for at least one happy-path and one error-path test per new method."
            ));
        }

        // ── Quality: large diff warning ───────────────────────────────────────
        long addedLines = java.util.Arrays.stream(lines)
                .filter(l -> l.startsWith("+") && !l.startsWith("+++"))
                .count();
        if (addedLines > 200) {
            findings.add(new Finding(
                    review,
                    "Large changeset — consider splitting",
                    "low",
                    "quality",
                    "unknown",
                    0,
                    "[MOCK] The diff adds more than 200 lines. Large pull requests are harder to review " +
                    "thoroughly and statistically introduce more defects.",
                    "Split this change into smaller, independently reviewable pull requests " +
                    "focused on a single concern."
            ));
        }

        return findings;
    }

    // ── Pattern helpers ───────────────────────────────────────────────────────

    private boolean containsCredentialPattern(String line) {
        String lower = line.toLowerCase();
        return (lower.contains("password") || lower.contains("passwd") ||
                lower.contains("secret") || lower.contains("apikey") ||
                lower.contains("api_key") || lower.contains("token"))
               && (line.contains("=") || line.contains(":"))
               && (line.contains("\"") || line.contains("'"));
    }

    private boolean containsSqlConcatPattern(String line) {
        String lower = line.toLowerCase();
        return lower.contains("select") && lower.contains("+") &&
               (lower.contains("where") || lower.contains("from"));
    }

    private boolean containsTodoFixme(String line) {
        String upper = line.toUpperCase();
        return upper.contains("TODO") || upper.contains("FIXME") || upper.contains("HACK");
    }

    private boolean containsEmptyCatch(String line) {
        // Matches: "} catch" with nothing meaningful after it on the same line
        return line.matches(".*}\\s*catch\\s*\\(.*\\)\\s*\\{?\\s*") ||
               line.matches(".*catch\\s*\\(.*\\)\\s*\\{\\s*}.*");
    }

    private boolean containsOptionalGetWithoutCheck(String line) {
        return line.contains(".get()") && !line.contains("isPresent") &&
               !line.contains("orElse") && !line.contains("ifPresent");
    }

    /**
     * Attempts to extract the nearest diff file header above line {@code lineIndex}.
     * Returns "unknown" when no header is found.
     */
    private String guessFile(String diff, int lineIndex) {
        String[] lines = diff.split("\n");
        for (int i = lineIndex; i >= 0; i--) {
            String l = lines[i];
            if (l.startsWith("+++ ")) {
                return l.replace("+++ b/", "").replace("+++ ", "").trim();
            }
            if (l.startsWith("--- ")) {
                return l.replace("--- a/", "").replace("--- ", "").trim();
            }
        }
        return "unknown";
    }
}

