12 | /**
13 |  * Rule CRED-001 — Hardcoded password, API key, token, or secret literal.
14 |  *
15 |  * <h3>What it detects</h3>
16 |  * Lines that assign a string literal to an identifier whose name suggests
17 |  * a credential ({@code password}, {@code passwd}, {@code secret},
18 |  * {@code apikey}, {@code api_key}, {@code token}, {@code authtoken},
19 |  * {@code access_key}, {@code private_key}).
20 |  *
21 |  * <h3>False-positive reduction</h3>
22 |  * <ul>
23 |  *   <li>Lines where the value is an empty string ({@code ""} or {@code ''})
24 |  *       are skipped — empty is a placeholder, not a real secret.</li>
25 |  *   <li>Lines where the value is a well-known placeholder
26 |  *       ({@code <...>}, {@code ${...}}, {@code %s}, {@code ?},
27 |  *       {@code changeme}, {@code yourpassword}, {@code example},
28 |  *       {@code placeholder}, {@code todo}, {@code fixme}) are skipped.</li>
29 |  *   <li>Lines inside obvious unit-test files (path ends with
30 |  *       {@code Test.java} or {@code Tests.java}) are reported at
31 |  *       {@code low} severity rather than {@code critical}.</li>
32 |  *   <li>Lines that are pure comments are skipped.</li>
33 |  * </ul>
34 |  *
35 |  * <h3>Limitations</h3>
36 |  * <ul>
37 |  *   <li>Does not inspect values passed via constructors or method
38 |  *       arguments unless the argument contains a quoted literal.</li>
39 |  *   <li>Environment-variable lookups ({@code System.getenv(...)}) are
40 |  *       not flagged — those are intentionally safe.</li>
41 |  * </ul>
42 |  */
43 | public class HardcodedCredentialRule implements AnalysisRule {
44 | 
45 |     /**
46 |      * Matches: identifier whose name is credential-like, followed by
47 |      * {@code =}, {@code :}, or in a method-call context,
48 |      * then a quoted string literal.
49 |      *
50 |      * Group 1: the credential-like keyword
51 |      * Group 2: the literal value (content between the quotes)
52 |      */
53 |     private static final Pattern CREDENTIAL_ASSIGNMENT = Pattern.compile(
54 |             "(?i)\\b(password|passwd|secret|api[_-]?key|token|auth[_-]?token" +
55 |             "|access[_-]?key|private[_-]?key)\\b" +
56 |             "\\s*(?:=|:)\\s*" +
57 |             "[\"']([^\"']{1,200})[\"']"
58 |     );
59 | 
60 |     /** Known safe placeholder values (checked case-insensitively). */
61 |     private static final List<String> PLACEHOLDERS = List.of(
62 |             "changeme", "yourpassword", "your_password", "example", "placeholder",
63 |             "todo", "fixme", "insert_here", "replace_me", "secret_here",
64 |             "password_here", "token_here", "xxxx", "****"
65 |     );
66 | 
67 |     /** Template / config-file substitution patterns: ${...}, %s, <...>, {env:...} */
68 |     private static final Pattern TEMPLATE_VALUE = Pattern.compile(
69 |             "^\\s*(?:\\$\\{[^}]+}|%[sd]|<[^>]+>|\\{[^}]+})\\s*$"
70 |     );
71 | 
72 |     @Override
73 |     public String ruleId() { return "CRED-001"; }
74 | 
75 |     @Override
76 |     public String name() { return "Hardcoded Credential Literal"; }
77 | 
78 |     @Override
79 |     public List<RuleFinding> analyze(List<DiffLine> addedLines) {
80 |         List<RuleFinding> findings = new ArrayList<>();
81 | 
82 |         for (DiffLine dl : addedLines) {
83 |             String content = dl.getContent();
84 | 
85 |             // Skip pure comment lines
86 |             if (isPureComment(content)) continue;
87 | 
88 |             Matcher m = CREDENTIAL_ASSIGNMENT.matcher(content);
89 |             while (m.find()) {
90 |                 String keyword = m.group(1);
91 |                 String value   = m.group(2);
92 | 
93 |                 // Skip empty values
94 |                 if (value.isEmpty()) continue;
95 | 
96 |                 // Skip template / substitution patterns
97 |                 if (TEMPLATE_VALUE.matcher(value).matches()) continue;
98 | 
99 |                 // Skip known placeholder words
100 |                 if (isPlaceholder(value)) continue;
101 | 
102 |                 // System.getenv / System.getProperty calls are not hardcoded
103 |                 if (content.contains("System.getenv") || content.contains("System.getProperty")
104 |                         || content.contains("env.get") || content.contains("getenv(")) continue;
105 | 
106 |                 boolean isTestFile = dl.getFile() != null &&
107 |                         (dl.getFile().endsWith("Test.java") || dl.getFile().endsWith("Tests.java"));
108 | 
109 |                 String severity = isTestFile ? "low" : "critical";
110 |                 String evidence = truncate(content.trim(), 120);
111 | 
112 |                 findings.add(RuleFinding.builder()
113 |                         .ruleId(ruleId())
114 |                         .title("Hardcoded " + keyword.toLowerCase() + " literal detected")
115 |                         .severity(severity)
116 |                         .category("security")
117 |                         .location(dl.getFile(), dl.getLineNumber())
118 |                         .description(String.format(
119 |                                 "[%s] A string literal that appears to be a credential was found " +
120 |                                 "assigned to an identifier named '%s'. Hardcoded secrets in source " +
121 |                                 "code are exposed to anyone with repository access and are " +
122 |                                 "permanently preserved in commit history even after deletion. " +
123 |                                 "Evidence: `%s`%s",
124 |                                 ruleId(), keyword, evidence,
125 |                                 isTestFile ? " (Found in test file — severity downgraded to low.)" : ""))
126 |                         .suggestion(
127 |                                 "Remove the literal value and load it at runtime from a " +
128 |                                 "secure source: an environment variable (System.getenv), " +
129 |                                 "a Spring @Value property backed by a secrets manager " +
130 |                                 "(e.g. HashiCorp Vault, AWS Secrets Manager, Azure Key Vault), " +
131 |                                 "or a configuration service. Rotate the secret if it was " +
132 |                                 "already committed.")
133 |                         .build());
134 |             }
135 |         }
136 | 
137 |         return findings;
138 |     }
139 | 
140 |     // ── helpers ──────────────────────────────────────────────────────────────
141 | 
142 |     private static boolean isPureComment(String content) {
143 |         String trimmed = content.stripLeading();
144 |         return trimmed.startsWith("//") || trimmed.startsWith("*")
145 |                 || trimmed.startsWith("/*") || trimmed.startsWith("#");
146 |     }
147 | 
148 |     private static boolean isPlaceholder(String value) {
149 |         String lower = value.toLowerCase();
150 |         for (String ph : PLACEHOLDERS) {
151 |             if (lower.equals(ph) || lower.contains(ph)) return true;
152 |         }
153 |         return false;
154 |     }
155 | 
156 |     private static String truncate(String s, int max) {
157 |         return s.length() <= max ? s : s.substring(0, max) + "…";
158 |     }
