105 |     // ── Template helpers ──────────────────────────────────────────────────────
106 | 
107 |     private String buildTestName(Finding f) {
108 |         switch (f.getSeverity() == null ? "" : f.getSeverity().toLowerCase()) {
109 |             case "critical": return "should fail securely when: " + lowerFirst(f.getTitle());
110 |             case "high":     return "should reject unsafe input: " + lowerFirst(f.getTitle());
111 |             case "medium":   return "should handle edge case: " + lowerFirst(f.getTitle());
112 |             default:         return "should satisfy: " + lowerFirst(f.getTitle());
113 |         }
114 |     }
115 | 
116 |     private String buildFilename(Finding f) {
117 |         String base = f.getFile() == null ? "unknown" : f.getFile()
118 |                 .replaceAll("[^a-zA-Z0-9/._-]", "_")
119 |                 .replaceFirst("\\.[^.]+$", "");
120 |         return "tests/" + base + "_finding_" + f.getId() + ".test.js";
121 |     }
122 | 
123 |     private String buildTestCode(Finding f) {
124 |         return "// [MOCK GENERATED TEST] — not executed\n" +
125 |                "// Finding: " + f.getTitle() + "\n" +
126 |                "// Severity: " + f.getSeverity() + " | Category: " + f.getCategory() + "\n" +
127 |                "// File: " + f.getFile() + ":" + f.getLine() + "\n\n" +
128 |                "describe('" + escapeJs(f.getTitle()) + "', () => {\n" +
129 |                "  it('" + escapeJs(buildTestName(f)) + "', () => {\n" +
130 |                "    // TODO: implement test for finding #" + f.getId() + "\n" +
131 |                "    // Suggestion: " + (f.getSuggestion() == null ? "see finding description" : f.getSuggestion()) + "\n" +
132 |                "    expect(true).toBe(true); // placeholder\n" +
133 |                "  });\n" +
134 |                "});\n";
135 |     }
136 | 
137 |     private String buildSecuritySmokeTest(Review review) {
138 |         return "// [MOCK GENERATED TEST] — not executed\n" +
139 |                "// Review #" + review.getId() + ": " + review.getTitle() + "\n\n" +
140 |                "describe('Review #" + review.getId() + " security smoke test', () => {\n" +
141 |                "  it('diff does not introduce new critical security findings', () => {\n" +
142 |                "    // This test would assert that the code changes do not\n" +
143 |                "    // introduce hardcoded credentials, injection vectors, etc.\n" +
144 |                "    expect(true).toBe(true); // placeholder — replace with real assertions\n" +
145 |                "  });\n" +
146 |                "});\n";
147 |     }
148 | 
149 |     private String lowerFirst(String s) {
150 |         if (s == null || s.isEmpty()) return s;
151 |         return Character.toLowerCase(s.charAt(0)) + s.substring(1);
152 |     }
153 | 
154 |     private String escapeJs(String s) {
155 |         return s == null ? "" : s.replace("'", "\\'");
156 |     }
157 | 
158 |     private Review getReviewOrThrow(Long reviewId) {
159 |         return reviewRepository.findById(reviewId)
160 |                 .orElseThrow(() -> new ResourceNotFoundException(
161 |                         "Review not found with id: " + reviewId));
162 |     }
163 | }
