3 | import java.util.ArrayList;
4 | import java.util.List;
5 | import java.util.regex.Matcher;
6 | import java.util.regex.Pattern;
7 | 
8 | /**
9 |  * Parses a unified diff ({@code git diff} output) and extracts every
10 |  * <em>added</em> line together with its file path and target line number.
11 |  *
12 |  * <h3>Parsing algorithm</h3>
13 |  * <ol>
14 |  *   <li>Track the current file by scanning {@code +++ b/...} headers.</li>
15 |  *   <li>Parse hunk headers ({@code @@ -a,b +c,d @@}) to determine the
16 |  *       starting target line number for the hunk.</li>
17 |  *   <li>For each line in the hunk:
18 |  *       <ul>
19 |  *         <li>{@code +} prefix → added line; record file + current target
20 |  *             line counter, advance counter.</li>
21 |  *         <li>{@code -} prefix → removed line; do NOT advance target
22 |  *             counter.</li>
23 |  *         <li>space prefix → context line; advance target counter.</li>
24 |  *       </ul>
25 |  *   </li>
26 |  * </ol>
27 |  *
28 |  * <p><strong>Limitations</strong>: binary diffs, {@code diff --stat} output,
29 |  * and non-standard diff formats are not handled; the parser silently skips
30 |  * unrecognised lines.  If the input is not a proper unified diff (e.g. the
31 |  * user pastes raw code), lines that start with {@code +} and are not preceded
32 |  * by a hunk header are collected with {@code lineNumber = 0} and
33 |  * {@code file = "unknown"}.
34 |  */
35 | public final class DiffParser {
36 | 
37 |     /**
38 |      * {@code @@ -oldStart[,oldLen] +newStart[,newLen] @@} — only the
39 |      * {@code +newStart} component is captured (group 1).
40 |      */
41 |     private static final Pattern HUNK_HEADER =
42 |             Pattern.compile("^@@\\s+-\\d+(?:,\\d+)?\\s+\\+(\\d+)(?:,\\d+)?\\s+@@");
43 | 
44 |     // private constructor — utility class
45 |     private DiffParser() {}
46 | 
47 |     /**
48 |      * Parse the supplied diff text and return all added lines with metadata.
49 |      *
50 |      * @param diff unified diff text; may be {@code null} or empty.
51 |      * @return ordered list of added {@link DiffLine}s; empty when nothing
52 |      *         could be parsed.
53 |      */
54 |     public static List<DiffLine> parse(String diff) {
55 |         List<DiffLine> result = new ArrayList<>();
56 |         if (diff == null || diff.isBlank()) return result;
57 | 
58 |         String[] lines  = diff.split("\n", -1);
59 |         String   file   = "unknown";
60 |         int      target = 0;      // current target (new file) line counter
61 | 
62 |         for (String raw : lines) {
63 | 
64 |             // ── File header ─────────────────────────────────────────────
65 |             if (raw.startsWith("+++ ")) {
66 |                 file   = extractFile(raw);
67 |                 target = 0;
68 |                 continue;
69 |             }
70 |             // Skip "--- " header lines
71 |             if (raw.startsWith("--- ")) {
72 |                 continue;
73 |             }
74 | 
75 |             // ── Hunk header ─────────────────────────────────────────────
76 |             if (raw.startsWith("@@")) {
77 |                 Matcher m = HUNK_HEADER.matcher(raw);
78 |                 if (m.find()) {
79 |                     target = Integer.parseInt(m.group(1));
80 |                 } else {
81 |                     target = 0; // can't determine position
82 |                 }
83 |                 continue;
84 |             }
85 | 
86 |             // ── Added line ──────────────────────────────────────────────
87 |             if (raw.startsWith("+")) {
88 |                 String content = raw.substring(1); // strip leading '+'
89 |                 result.add(new DiffLine(file, target, content));
90 |                 if (target > 0) target++;
91 |                 continue;
92 |             }
93 | 
94 |             // ── Removed line ─────────────────────────────────────────────
95 |             if (raw.startsWith("-")) {
96 |                 // removed line: target counter does NOT advance
97 |                 continue;
98 |             }
