    /**
     * Generate test code for a finding.
     *
     * @param f the finding to generate a test for
     * @return a non-null, non-empty string of test source code
     */
    public static String generate(Finding f) {
        String ruleId = extractRuleId(f.getDescription());
        return switch (ruleId) {
            case "SQLI-001"  -> sqlInjectionTest(f);
            case "CRED-001"  -> hardcodedCredentialTest(f);
            case "EXEC-001"  -> dangerousExecutionTest(f);
